class Solution {
    fun nthMagicalNumber(n:Int,a:Int,b:Int):Int{
        val lcm=a.toLong()/gcd(a,b)*b;
        var low=1L;
        var high=n.toLong()*minOf(a,b);
        while(low<high){
            val middle=low+(high-low)/2;
            val count=middle/a+middle/b-middle/lcm;
            if(count>=n)high=middle else low=middle+1
        };
        return(low%1000000007).toInt()
    };
    private fun gcd(aInput:Int,bInput:Int):Int{
        var a=aInput;
        var b=bInput;
        while(b!=0){
            val temporary=a%b;
            a=b;
            b=temporary
        };
        return a
    }
}

